const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var nyc = ee.Geometry.Point([-74.0060, 40.7128]).buffer(20000); // 20km buffer around NYC
  var date = '2023-08-09';

  // Time windows in UTC (EDT = UTC-4)
  var afternoonStart = 18; // 2:00-3:00 pm EDT = 18-19 UTC
  var afternoonEnd = 19;
  var eveningStart = 21;   // 5:00-6:00 pm EDT = 21-22 UTC
  var eveningEnd = 22;

  // Function to get NO2 mean for a given hour range
  async function getNO2Mean(startHour, endHour, label) {
    // Try multiple collections in order of preference
    var collections = [
      'COPERNICUS/S5P/OFFL/L2_NO2',
      'COPERNICUS/S5P/NRTI/L2_NO2',
      'COPERNICUS/S5P/NRTI/L3_NO2'  // hourly aggregated
    ];

    var col = null;
    var colName = '';

    for (var i = 0; i < collections.length; i++) {
      var candidate = ee.ImageCollection(collections[i])
        .filterDate(date, ee.Date(date).advance(1, 'day'))
        .filter(ee.Filter.hourOfDay({start: startHour, end: endHour}))
        .filterBounds(nyc);

      var size = candidate.size().getInfo();
      if (size > 0) {
        col = candidate;
        colName = collections[i];
        break;
      }
    }

    if (col === null) {
      console.log(label + ': No images found');
      return {mean: null, count: 0};
    }

    console.log(label + ' Images: ' + col.size().getInfo() + ' (' + colName + ')');

    // Mask clouds and select NO2 band
    var masked = col.map(function(image) {
      // Different collections have different cloud masks
      var cloudMask;
      if (colName.includes('L2')) {
        cloudMask = image.select('cloud_fraction').lt(0.3);
      } else {
        // L3 product may not have cloud_fraction, use QA
        cloudMask = image.select('qa_value').gt(0.5);
      }
      return image.select('NO2_column_number_density')
                  .updateMask(cloudMask);
    });

    // Create composite
    var composite = masked.mean();

    // Get mean and count
    var stats = composite.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: nyc,
      scale: 1000,
      maxPixels: 1e9
    });

    var mean = stats.get('NO2_column_number_density').getInfo();
    var count = stats.get('NO2_column_number_density_count').getInfo();

    return {mean: mean, count: count};
  }

  // 2. Get NO2 for both time windows
  var afternoon = await getNO2Mean(afternoonStart, afternoonEnd, 'Afternoon (2-3pm EDT)');
  var evening = await getNO2Mean(eveningStart, eveningEnd, 'Evening (5-6pm EDT)');

  // 3. Check for data availability issues
  if (afternoon.mean === null || evening.mean === null) {
    console.log('One or both time windows have no data');
    console.log('<answer>C1</answer>');
    return;
  }

  if (afternoon.count === 0 || evening.count === 0) {
    console.log('Afternoon valid pixels: ' + afternoon.count);
    console.log('Evening valid pixels: ' + evening.count);
    console.log('No valid pixels after masking');
    console.log('<answer>C2</answer>');
    return;
  }

  // 4. Validate the values
  if (afternoon.mean === null || evening.mean === null || 
      isNaN(afternoon.mean) || isNaN(evening.mean) ||
      afternoon.mean < 0 || evening.mean < 0) { // NO2 should be positive
    console.log('Afternoon mean: ' + afternoon.mean);
    console.log('Evening mean: ' + evening.mean);
    console.log('Invalid NO2 values');
    console.log('<answer>C3</answer>');
    return;
  }

  // 5. Compare and output
  console.log('Afternoon NO2 mean: ' + afternoon.mean.toFixed(6) + ' mol/m²');
  console.log('Evening NO2 mean: ' + evening.mean.toFixed(6) + ' mol/m²');
  console.log('Afternoon pixels: ' + afternoon.count);
  console.log('Evening pixels: ' + evening.count);

  if (afternoon.mean > evening.mean) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
